def feature(text: str) -> float:
    'Named entity ratio in the text'
    doc = nlp(text)
    entity_count = len(doc.ents)
    total_tokens = len(doc)
    return (entity_count / total_tokens) if total_tokens > 0 else 0.0

def feature(text: str) -> float:
