    return sum(len(word) for word in words) / len(words)

def feature(text: str) -> float:
    'Standard deviation of word lengths'
    words = text.split()
    lengths = [len(word) for word in words]
    if len(lengths) < 2:
        return 0.0
    return float(statistics.pstdev(lengths))

def feature(text: str) -> float:
