def feature(text: str) -> float:
    "Count of points of view used in the text (1st, 2nd, 3rd person)"
    pov_count = sum(1 for token in nlp(text) if token.text in {'I', 'you', 'he', 'she', 'they', 'we'})
    return float(pov_count)

def feature(text: str) -> float:
    "Standard deviation of word lengths in the text"
    words = [len(word) for word in text.split()]
    if not words:
        return 0.0
    mean_length = sum(words) / len(words)
    variance = sum((x - mean_length) ** 2 for x in words) / len(words)
    return float(variance ** 0.5)
def feature(text: str) -> float:
    "Ratio of punctuation marks to total characters in the text"
    punctuation_count = sum(1 for c in text if not c.isalnum() and not c.isspace())
    total_characters = len(text)
    return (punctuation_count / total_characters) if total_characters > 0 else 0.0

def feature(text: str) -> float:
    "Average number of words per sentence"
    sentences = re.split(r'[.!?]+', text)
    word_count = len(text.split())
    sentence_count = len([s for s in sentences if s.strip()])
    return (word_count / sentence_count) if sentence_count > 0 else 0.0

