def feature(text: str) -> float:
    'Difference in average word length between questions and statements'
    sentences = re.split(r'[.!?]+', text)
    questions = [s for s in sentences if s.strip().endswith('?')]
    statements = [s for s in sentences if not s.strip().endswith('?')]
    avg_question_length = sum(len(s.split()) for s in questions) / len(questions) if questions else 0.0
    avg_statement_length = sum(len(s.split()) for s in statements) / len(statements) if statements else 0.0
    return avg_question_length - avg_statement_length
