        if not list(token.children):
            return 0
        return 1 + max(get_tree_depth(child) for child in token.children)

    doc = nlp(text)
    depths = [get_tree_depth(sent.root) for sent in doc.sents] if list(doc.sents) else []
    return float(statistics.mean(depths)) if depths else 0.0

