def feature(text: str) -> float:
    'Average distance to the nearest punctuation mark for each word'
    punctuation_positions = [i for i, char in enumerate(text) if char in string.punctuation]
    if not punctuation_positions or len(punctuation_positions) == len(text):
        return 0.0
    total_distance = 0
    words = text.split()
    for word in words:
        word_index = text.find(word)
        distances = [abs(word_index - pos) for pos in punctuation_positions]
        total_distance += min(distances) if distances else 0
    return total_distance / len(words)

