    "Average syllables per word in the text"
    words = text.split()
    if not words:
        return 0.0
    syllable_counts = [textstat.syllable_count(word) for word in words]
    return float(sum(syllable_counts)) / len(words)

def feature(text: str) -> float:
    "Percentage of sentences with questions in the text"
    sentences = re.split(r'[.!?]+', text)
    question_count = sum(1 for s in sentences if s.strip().endswith('?'))
    return float(question_count) / len(sentences) if sentences else 0.0
def feature(text: str) -> float:
